// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;
    function setUp() public {
        c = new TimelockController(0, new address[](0), new address[](0));
    }

    function testFuzz_property(bytes32 role) public {
        vm.assume(role != bytes32(0));
        vm.assume(role != c.DEFAULT_ADMIN_ROLE());
        vm.assume(role != c.TIMELOCK_ADMIN_ROLE());
        vm.assume(role != c.PROPOSER_ROLE());
        vm.assume(role != c.EXECUTOR_ROLE());

        bytes32 admin = c.getRoleAdmin(c.TIMELOCK_ADMIN_ROLE());
        assertTrue(admin == c.TIMELOCK_ADMIN_ROLE());
    }
}
